(()=>{const page=location.pathname.replace(/^\/+|\/+$/g,'')||'home';if(!['home','pricing'].includes(page))return;const details=[['Quick Start','Flexible monthly access for trying Tivione on your favourite devices.'],['More Time','A simple three-month choice for a longer viewing season.'],['Balanced Choice','Six months of stable streaming, movies, series and global EPG.'],['Year-Round Access','A complete 12-month plan for everyday entertainment.'],['Long-Term Value','Our best-value 24-month plan for uninterrupted viewing.']];const plans=[...document.querySelectorAll('.plan')];plans.forEach((plan,i)=>{const d=details[i%details.length];if(!plan.querySelector('.plan-media'))plan.insertAdjacentHTML('afterbegin','<div class="plan-media"><img src="/assets/tivione.webp" alt="Tivione IPTV plan"></div>');const title=plan.querySelector('h3');if(title){title.insertAdjacentHTML('afterend','<p class="plan-title">'+d[0]+'</p><p class="plan-description">'+d[1]+'</p>');}});if(page==='pricing'){const grid=document.querySelector('main > section .grid.five');if(grid)grid.classList.add('subscription-row-plans');}})();
